"""ElevenLabs Scribe v2 Realtime ASR engine implementation."""

import base64
import json
import os
from typing import Any, Dict, List, Literal, Optional
from urllib.parse import urlencode

import structlog
import websockets.exceptions
from websockets.asyncio.client import ClientConnection, connect
from websockets.protocol import State

from rasa.core.channels.voice_stream.asr.asr_engine import (
    ASREngine,
    ASREngineConfig,
    ASRLanguageMapEntry,
)
from rasa.core.channels.voice_stream.asr.asr_event import (
    ASREvent,
    NewTranscript,
    UserIsSpeaking,
)
from rasa.core.channels.voice_stream.audio_bytes import (
    L16_16KHZ,
    L16_24KHZ,
    L16_48KHZ,
    MULAW_8KHZ,
    AudioFormat,
    RasaAudioBytes,
)
from rasa.shared.constants import ELEVENLABS_API_KEY_ENV_VAR
from rasa.shared.exceptions import ConnectionException

logger = structlog.get_logger(__name__)

DEFAULT_ENDPOINT = "wss://api.elevenlabs.io/v1/speech-to-text/realtime"
DEFAULT_MODEL = "scribe_v2_realtime"
_AUDIO_BATCH_DURATION_MS = 100


class ElevenLabsASRConfig(ASREngineConfig):
    """Configuration for ElevenLabs Scribe v2 Realtime."""

    endpoint: str = DEFAULT_ENDPOINT
    commit_strategy: Literal["vad", "manual"] = "vad"
    include_timestamps: bool = False
    include_language_detection: bool = False


class ElevenLabsASR(ASREngine[ElevenLabsASRConfig]):
    """Transcribe streamed caller audio with ElevenLabs Scribe v2 Realtime."""

    required_env_vars = (ELEVENLABS_API_KEY_ENV_VAR,)

    def __init__(
        self,
        rasa_language: str,
        format: AudioFormat,
        config: Optional[ElevenLabsASRConfig] = None,
        additional_languages: Optional[List[str]] = None,
    ) -> None:
        super().__init__(rasa_language, format, config, additional_languages)
        self._audio_buffer = bytearray()
        self._audio_batch_size = max(
            1, self.audio_format.bytes_per_second * _AUDIO_BATCH_DURATION_MS // 1000
        )

    @classmethod
    def name(cls) -> str:
        """Return the name identifier for this ASR engine."""
        return "elevenlabs"

    async def open_websocket_connection(self) -> ClientConnection:
        """Connect to the ElevenLabs realtime speech-to-text endpoint."""
        audio_formats = {
            MULAW_8KHZ: "ulaw_8000",
            L16_16KHZ: "pcm_16000",
            L16_24KHZ: "pcm_24000",
            L16_48KHZ: "pcm_48000",
        }
        audio_format = audio_formats.get(self.audio_format)
        if audio_format is None:
            raise ConnectionException(
                f"Unsupported ElevenLabs ASR audio format: {self.audio_format}"
            )

        query_params: Dict[str, Any] = {
            "model_id": self.current_language_config.model or DEFAULT_MODEL,
            "audio_format": audio_format,
            "commit_strategy": self.config.commit_strategy,
            "include_timestamps": str(self.config.include_timestamps).lower(),
            "include_language_detection": str(
                self.config.include_language_detection
            ).lower(),
        }
        if (
            self.current_language_config.engine_language_key
            and not self.config.include_language_detection
        ):
            query_params["language_code"] = (
                self.current_language_config.engine_language_key
            )

        url = f"{self.config.endpoint}?{urlencode(query_params)}"
        try:
            return await connect(
                url,
                additional_headers={
                    "xi-api-key": os.environ[ELEVENLABS_API_KEY_ENV_VAR],
                },
            )
        except websockets.exceptions.InvalidStatus as error:
            logger.error(
                "elevenlabs.asr.connection_failed",
                status_code=error.response.status_code,
            )
            if error.response.status_code == 401:
                raise ConnectionException(
                    "ElevenLabs authentication failed; check ELEVENLABS_API_KEY."
                ) from error
            raise ConnectionException("Connection to ElevenLabs ASR failed.") from error

    async def send_audio_chunks(self, chunk: RasaAudioBytes) -> None:
        """Batch short audio frames before sending them to ElevenLabs."""
        async with self._get_engine_lock():
            socket = self.asr_socket
            if socket is None or socket.state is not State.OPEN:
                logger.debug(
                    "asr.elevenlabs.send_audio_chunks.skipped",
                    reason=(
                        "socket_not_connected" if socket is None else "socket_closed"
                    ),
                )
                self._audio_buffer.clear()
                return

            self._audio_buffer.extend(chunk.data)
            if len(self._audio_buffer) >= self._audio_batch_size:
                await self._send_audio_buffer(socket)

    async def _send_audio_buffer(self, socket: ClientConnection) -> None:
        if not self._audio_buffer:
            return

        audio_data = bytes(self._audio_buffer)
        self._audio_buffer.clear()
        message = {
            "message_type": "input_audio_chunk",
            "audio_base_64": base64.b64encode(audio_data).decode("ascii"),
            "sample_rate": self.audio_format.sample_rate,
        }
        try:
            await socket.send(json.dumps(message))
        except (
            websockets.exceptions.ConnectionClosedOK,
            websockets.exceptions.ConnectionClosedError,
        ) as error:
            logger.debug(
                "asr.elevenlabs.send_audio_chunks.connection_closed",
                error=str(error),
            )

    async def close_connection(self) -> None:
        await self._flush_audio_buffer()
        await super().close_connection()

    async def _flush_audio_buffer(self) -> None:
        socket = self.asr_socket
        if socket is None or socket.state is not State.OPEN:
            self._audio_buffer.clear()
            return
        await self._send_audio_buffer(socket)

    async def signal_audio_done(self) -> None:
        """Commit any buffered audio when using manual commit mode."""
        async with self._get_engine_lock():
            await self._flush_audio_buffer()
            socket = self.asr_socket
            if (
                self.config.commit_strategy == "manual"
                and socket is not None
                and socket.state is State.OPEN
            ):
                await socket.send(json.dumps({"message_type": "commit"}))

    def rasa_audio_bytes_to_engine_bytes(self, chunk: RasaAudioBytes) -> bytes:
        """Return the original audio bytes for the provider's base64 payload."""
        return chunk.data

    def engine_event_to_asr_event(self, event: Any) -> Optional[ASREvent]:
        """Translate one ElevenLabs websocket message into an ASR event."""
        try:
            data = json.loads(event) if isinstance(event, (str, bytes)) else event
        except (json.JSONDecodeError, UnicodeDecodeError):
            return None
        if not isinstance(data, dict):
            return None

        message_type = data.get("message_type")
        text = data.get("text")
        if not isinstance(text, str) or not text:
            return None
        if message_type == "partial_transcript":
            return UserIsSpeaking(text=text)
        if message_type in (
            "committed_transcript",
            "committed_transcript_with_timestamps",
        ):
            return NewTranscript(text=text)
        return None

    @staticmethod
    def get_default_config(rasa_language: str) -> ElevenLabsASRConfig:
        """Return the default Scribe v2 Realtime config for a language."""
        return ElevenLabsASRConfig(
            language_map={
                rasa_language: ASRLanguageMapEntry(
                    language=rasa_language,
                    model=DEFAULT_MODEL,
                ),
            },
        )

    @classmethod
    def from_config_dict(
        cls,
        config: Dict,
        format: AudioFormat,
        rasa_language: str,
        additional_languages: Optional[List[str]] = None,
    ) -> "ElevenLabsASR":
        """Create an ``ElevenLabsASR`` instance from a raw config dictionary."""
        return cls(
            rasa_language=rasa_language,
            format=format,
            config=ElevenLabsASRConfig.model_validate(config),
            additional_languages=additional_languages,
        )
